    // ── SOUNDNESS of the Init domain-bound derivation (finite-int-set membership + cross-column) ──
    // A too-tight bound that dropped a real Init state from `D` would be a FALSE SAFE; these pin the
    // bound VALUES (upper bounds, never too tight) and the fail-closed cases.

    /// `rdy ∈ {0,1}` recognizes (via `materialize_finite_int_set`/`fold_finite_expansion`) as the
    /// Or-fold of same-column Eq-literals ⇒ `H = max(literals) = 1`.
    #[test]
    fn init_bound_finite_int_set_membership_is_max_literal() {
        // Or(Eq(Var0,0), Or(Eq(Var0,1), Eq(Var0,2)))  ≡  rdy ∈ {0,1,2}
        let ir = PredIR::Or(
            Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(0))),
            Box::new(PredIR::Or(
                Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(1))),
                Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(2))),
            )),
        );
        let b = init_domain_bounds_cov_from_ir(&ir, 1, &[ColSort::Int]).expect("bounded");
        assert_eq!(
            b[0].0, 2,
            "H = max literal (2), covers every admissible rdy value"
        );
        // The coverage lemma is kernel-provable at the derived bound (or-elim + beq→ble pins).
        assert!(
            kernel_prove_init_coverage_column(&ir, 1, 2, 0),
            "Init ⇒ rdy ≤ 2 kernel-proven"
        );
        // A TOO-TIGHT bound (1, dropping the rdy=2 value) is NOT kernel-provable — fail-safe.
        assert!(
            !kernel_prove_init_coverage_column(&ir, 1, 1, 0),
            "too-tight H=1 must NOT prove"
        );
    }

    /// `rdy ∈ {0,1,2,3} ∧ ack = rdy` over `[rdy=Int(0), ack=Int(1)]`: `H_rdy = 3`, and `ack`
    /// inherits `H_ack = H_rdy = 3` (D's ack-axis is `0..3`, NOT tightened below rdy's range — a
    /// too-tight ack bound would drop a real Init state).
    #[test]
    fn init_bound_cross_column_equality_inherits_and_is_not_too_tight() {
        let rdy_in = PredIR::Or(
            Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(0))),
            Box::new(PredIR::Or(
                Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(1))),
                Box::new(PredIR::Or(
                    Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(2))),
                    Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Lit(3))),
                )),
            )),
        );
        // ack = rdy  ⇒  Eq(Var(ack=1), Var(rdy=0))
        let ir = PredIR::And(
            Box::new(rdy_in),
            Box::new(PredIR::Eq(ValIR::Var(1), ValIR::Var(0))),
        );
        let b =
            init_domain_bounds_cov_from_ir(&ir, 2, &[ColSort::Int, ColSort::Int]).expect("bounded");
        assert_eq!(b[0].0, 3, "H_rdy = max{{0,1,2,3}} = 3");
        assert_eq!(b[1].0, 3, "H_ack = H_rdy = 3 (0..3, not too tight)");
        // The ack cross-column coverage is kernel-provable at H=3; too-tight H=2 is NOT.
        assert!(
            kernel_prove_init_coverage_column(&ir, 2, 3, 1),
            "Init ⇒ ack ≤ 3 kernel-proven"
        );
        assert!(
            !kernel_prove_init_coverage_column(&ir, 2, 2, 1),
            "too-tight H_ack=2 must NOT prove"
        );
    }

    /// A dependency CYCLE `a = b ∧ b = a` with no literal anchor ⇒ both columns unbounded ⇒ the
    /// bound derivation DECLINES (fail-closed), so no fully-free Init leg is ever claimed.
    #[test]
    fn init_bound_cross_column_cycle_declines() {
        let ir = PredIR::And(
            Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Var(1))),
            Box::new(PredIR::Eq(ValIR::Var(1), ValIR::Var(0))),
        );
        assert!(
            init_domain_bounds_cov_from_ir(&ir, 2, &[ColSort::Int, ColSort::Int]).is_none(),
            "a=b ∧ b=a with no anchor must fail closed"
        );
    }

    /// A cross-column equality `a = b` whose target `b` is UNBOUNDED (no constraint) ⇒ DECLINE.
    #[test]
    fn init_bound_cross_column_forward_ref_unbounded_declines() {
        let ir = PredIR::Eq(ValIR::Var(0), ValIR::Var(1)); // a = b, b unconstrained
        assert!(
            init_domain_bounds_cov_from_ir(&ir, 2, &[ColSort::Int, ColSort::Int]).is_none(),
            "equality to an unbounded column must fail closed"
        );
        // But if `b` is anchored (b ≤ 5), `a` inherits it and BOTH are bounded.
        let ir2 = PredIR::And(
            Box::new(PredIR::Eq(ValIR::Var(0), ValIR::Var(1))),
            Box::new(PredIR::Leq(ValIR::Var(1), ValIR::Lit(5))),
        );
        let b = init_domain_bounds_cov_from_ir(&ir2, 2, &[ColSort::Int, ColSort::Int])
            .expect("anchored");
        assert_eq!((b[0].0, b[1].0), (5, 5), "a inherits b's anchored bound");
    }

    /// PROBE (before wiring): the COMPOSITION the Or coverage walk builds — or-elim applied at a
    /// SYMBOLIC (stuck) scrutinee, each continuation discharged by the `beq→ble` pin lemma. This
    /// is the HourClock two-arm shape reduced to its essence:
    ///   `Π(n:Nat). Eq (Bool.or (beq n 6) (beq n 1)) true → Eq (ble n 13) true`.
    #[test]
    fn probe_bool_or_elim_composes_with_beq_pins() {
        let beq = |a: Expr, b: Expr| Expr::apps(Expr::const_str("Nat.beq"), [a, b]);
        let ble = |a: Expr, b: Expr| Expr::apps(Expr::const_str("Nat.ble"), [a, b]);
        let bor = |a: Expr, b: Expr| Expr::apps(Expr::const_str("Bool.or"), [a, b]);
        // TYPE: Π(n:Nat). Eq (or (beq n 6) (beq n 1)) true → Eq (ble n 13) true
        let hyp = eq_bool(
            bor(
                beq(Expr::bvar(0), Expr::nat_lit(6)),
                beq(Expr::bvar(0), Expr::nat_lit(1)),
            ),
            bool_true(),
        );
        let goal = eq_bool(ble(Expr::bvar(1), Expr::nat_lit(13)), bool_true());
        let ty = Expr::pi(
            BinderInfo::Default,
            Expr::const_str("Nat"),
            Expr::pi(BinderInfo::Default, hyp.clone(), goal),
        );
        // TERM: λn h. or_elim (beq n 6) (beq n 1) (Eq (ble n 13) true) h
        //                (λh1. P(6,13) n h1) (λh2. P(1,13) n h2)
        // under [n, h]: n = 1, h = 0; inside each continuation n = 2, hk = 0.
        let goal_at_h = eq_bool(ble(Expr::bvar(1), Expr::nat_lit(13)), bool_true());
        let k = |c: u64| {
            Expr::lam(
                BinderInfo::Default,
                eq_bool(beq(Expr::bvar(1), Expr::nat_lit(c)), bool_true()),
                Expr::apps(
                    beq_to_ble_lemma(c, 13, true),
                    [Expr::bvar(2), Expr::bvar(0)],
                ),
            )
        };
        let body = Expr::apps(
            bool_or_elim_lemma(),
            [
                beq(Expr::bvar(1), Expr::nat_lit(6)),
                beq(Expr::bvar(1), Expr::nat_lit(1)),
                goal_at_h,
                Expr::bvar(0),
                k(6),
                k(1),
            ],
        );
        let tm = Expr::lam(
            BinderInfo::Default,
            Expr::const_str("Nat"),
            Expr::lam(BinderInfo::Default, hyp, body),
        );
        assert!(
            kernel_accepts(&tm, &ty),
            "or-elim must compose with the beq→ble pin lemmas"
        );
    }

    /// The HourClock `Next` AST `x' = IF x # 12 THEN x + 1 ELSE 1` (shared by the IF-desugaring
    /// tests below). `flip` puts the `IF` on the LEFT (`IF … = x'`) — recognition must normalize
    /// to the SAME IR (the value side first in each arm equality).
    fn hourclock_next_ast(flip: bool) -> tla_core::ast::Expr {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::Ident("x".to_string(), NameId::INVALID);
        let xp = || E::Prime(sp(x()));
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        let ite = E::If(
            sp(E::Neq(sp(x()), sp(lit(12)))),
            sp(E::Add(sp(x()), sp(lit(1)))),
            sp(lit(1)),
        );
        if flip {
            E::Eq(sp(ite), sp(xp()))
        } else {
            E::Eq(sp(xp()), sp(ite))
        }
    }

    /// The IR the desugaring must PIN: `(x≠12 ∧ x'=x+1) ∨ (¬(x≠12) ∧ x'=1)`.
    fn hourclock_next_ir() -> PredIR {
        let cond = || PredIR::Neq(ValIR::Var(0), ValIR::Lit(12));
        PredIR::Or(
            Box::new(PredIR::And(
                Box::new(cond()),
                Box::new(PredIR::Eq(
                    ValIR::Prime(0),
                    ValIR::Add(Box::new(ValIR::Var(0)), Box::new(ValIR::Lit(1))),
                )),
            )),
            Box::new(PredIR::And(
                Box::new(PredIR::Not(Box::new(cond()))),
                Box::new(PredIR::Eq(ValIR::Prime(0), ValIR::Lit(1))),
            )),
        )
    }

    /// PINNED RECOGNITION: `x' = IF c THEN a ELSE b` desugars to the exact
    /// `(c ∧ x'=a) ∨ (¬c ∧ x'=b)` Or-shape — in BOTH orientations (the flipped `IF … = x'`
    /// normalizes to the same IR, value side first). The desugaring is truth-exact in both
    /// directions (see `eq_if_form`), so nothing else in the pipeline needs an `If` node.
    #[test]
    fn recognize_if_then_else_eq_desugars_to_or() {
        let sorts = [ColSort::Int];
        let ir = recognize_pred_sorts(&hourclock_next_ast(false), &["x"], &sorts)
            .expect("the IF-hosted equality must recognize");
        assert_eq!(ir, hourclock_next_ir(), "pinned desugared Or shape");
        let flipped = recognize_pred_sorts(&hourclock_next_ast(true), &["x"], &sorts)
            .expect("the flipped orientation must recognize too");
        assert_eq!(
            flipped,
            hourclock_next_ir(),
            "orientation-normalized to the SAME IR"
        );
    }

    /// FAIL-CLOSED: an IF whose CONDITION is outside the fragment declines the whole equality;
    /// and the polarity-gated `Sub` form is forbidden INSIDE the condition (it appears under a
    /// `¬` in the desugaring ⇒ unknown polarity).
    #[test]
    fn recognize_if_then_else_fails_closed() {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::Ident("x".to_string(), NameId::INVALID);
        let xp = || E::Prime(sp(x()));
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        let sorts = [ColSort::Int];
        // Condition `y # 12` mentions an unknown variable ⇒ out of fragment ⇒ None.
        let bad_cond = E::Eq(
            sp(xp()),
            sp(E::If(
                sp(E::Neq(
                    sp(E::Ident("y".to_string(), NameId::INVALID)),
                    sp(lit(12)),
                )),
                sp(E::Add(sp(x()), sp(lit(1)))),
                sp(lit(1)),
            )),
        );
        assert!(recognize_pred_sorts(&bad_cond, &["x"], &sorts).is_none());
        // Condition `x = x - 1` hosts the polarity-gated Sub form, which is admitted ONLY at
        // strictly-positive polarity — the condition recurses at UNKNOWN (it is used under ¬
        // in the else arm), so this must fail closed.
        let sub_cond = E::Eq(
            sp(xp()),
            sp(E::If(
                sp(E::Eq(sp(x()), sp(E::Sub(sp(x()), sp(lit(1)))))),
                sp(E::Add(sp(x()), sp(lit(1)))),
                sp(lit(1)),
            )),
        );
        assert!(
            recognize_pred_sorts(&sub_cond, &["x"], &sorts).is_none(),
            "a Sub-form condition must fail closed (unknown polarity inside IF)"
        );
    }

    /// RULE 4 (Or-split) bounds + the KERNEL coverage upgrade for the IF-desugared Next: the
    /// disjunctive conjunct bounds column 0 by max(then-pin, else-pin) = max(max_R(x)+1, 1) = 13
    /// over R = {1..12}; and `kernel_prove_next_coverage_column` discharges the per-state
    /// Π-lemmas via the or-elimination walk (probe-verified lemmas), upgrading the axis to
    /// KernelProven — no Rust bound rule left in the trust story.
    #[test]
    fn if_desugared_next_bounds_and_kernel_coverage() {
        let ir = hourclock_next_ir();
        let reachable: Vec<Vec<u64>> = (1..=12u64).map(|v| vec![v]).collect();
        let sorts = [ColSort::Int];
        let bounds = next_domain_bounds_cov_from_ir(&ir, 1, &reachable, &sorts)
            .expect("RULE 4 must bound the Or-shaped Next");
        assert_eq!(
            bounds,
            vec![(13, DomainCoverage::RustDerived)],
            "max over arms: max(13,1)"
        );
        // The kernel proves the successor bound per state: or-elim on the disjunction, then the
        // And-projection walk to each arm's Eq-pin, discharged by the beq→ble lemma at H=13.
        assert!(
            kernel_prove_next_coverage_column(&ir, 1, &reachable, 13, 0),
            "the or-elimination coverage walk must be kernel-accepted for every s ∈ R"
        );
        // The upgrade pass must reflect it.
        let mut cov = bounds;
        upgrade_domain_coverage(&ir, 1, &reachable, &mut cov, true);
        assert_eq!(cov, vec![(13, DomainCoverage::KernelProven)]);
        // And a WRONG bound (too small for the then-arm pin at s=12 → 13 > 12) must NOT prove.
        assert!(
            !kernel_prove_next_coverage_column(&ir, 1, &reachable, 12, 0),
            "a bound the successors escape must be kernel-REJECTED"
        );
    }

    // ── Phase 0 axiom/trust gate (docs/kernel-checked-tla-plan.md) ───────────────────────────────
    // `with_prelude` seeds `sorry`/`trustedArith`/`trustedAy : {α:Sort u}→α`, so a term applying one
    // TYPE-CHECKS against a real obligation type yet proves nothing. `kernel_accepts` must therefore
    // check MORE than `check_type`: the term's transitive axiom closure must be foundational-only.

    /// A directly trust-marker-backed term type-checks but must NOT be promoted.
    #[test]
    fn gate_rejects_directly_trust_marker_backed_terms() {
        use clean_kernel::Level;
        let false_ty = Expr::const_str("False");
        for marker in ["sorry", "trustedArith", "trustedAy"] {
            // `<marker>.{0} False : False`
            let term = Expr::apps(
                Expr::const_str_levels(marker, vec![Level::zero()]),
                [false_ty.clone()],
            );
            // (a) the kernel genuinely type-checks it — the soundness hole is real.
            let env = Environment::with_prelude();
            let tc = TypeChecker::new(&env);
            assert!(
                tc.check_type(&term, &false_ty).is_ok(),
                "`{marker}.<0> False : False` must type-check (that IS the soundness hole)"
            );
            // (b) but the Phase-0 gate must refuse to promote it.
            assert!(
                !kernel_accepts(&term, &false_ty),
                "kernel_accepts must REJECT a `{marker}`-backed term (never a false Certified)"
            );
        }
    }

    /// The gate must catch a trust marker reached TRANSITIVELY through an intermediate definition —
    /// the case a shallow scan of the proof term (which sees only the intermediate's name) misses.
    #[test]
    fn gate_rejects_trust_marker_reached_through_a_definition() {
        use clean_kernel::Level;
        let false_ty = Expr::const_str("False");
        let mut env = Environment::with_prelude();
        // Intermediate: `TyPhase0Laundered : False := trustedArith.{0} False` (structurally admitted).
        let laundered = Expr::apps(
            Expr::const_str_levels("trustedArith", vec![Level::zero()]),
            [false_ty.clone()],
        );
        env.add_decl_structural(Declaration::Theorem {
            name: Name::from_string("TyPhase0Laundered"),
            level_params: Vec::new(),
            type_: false_ty.clone(),
            value: laundered,
        })
        .expect("structural insert of the intermediate lemma");
        // The proof term cites ONLY `TyPhase0Laundered` — its own head is not a trust marker, so a
        // shallow term scan would pass it. The transitive closure gate must still reject it.
        let term = Expr::const_str("TyPhase0Laundered");
        assert!(
            !term_reaches_no_trust_marker(env, &false_ty, &term),
            "the gate must follow the transitive closure through the definition to the trust marker"
        );
    }

    /// Phase-0 SCOPE BOUNDARY: a merely-admitted *domain* axiom (NOT a trust marker) is currently
    /// ALLOWED through the gate — this is the deliberate scope decision (blocking these is plan item
    /// B#3, repoint to a marker-free env). But it is not hidden: `axiom_deps` still SURFACES it, so a
    /// verdict resting on it is honestly `AxiomDependent`. (This is exactly the set fragment's status,
    /// whose bitmask lemmas are admitted domain axioms — which is why the gate blocks trust markers,
    /// not the whole non-foundational closure.)
    #[test]
    fn gate_allows_but_surfaces_a_non_marker_domain_axiom() {
        let false_ty = Expr::const_str("False");
        let mut env = Environment::with_prelude();
        env.add_decl_structural(Declaration::Axiom {
            name: Name::from_string("TyPhase0DomainAxiom"),
            level_params: Vec::new(),
            type_: false_ty.clone(),
        })
        .expect("structural insert of a domain axiom");
        let term = Expr::const_str("TyPhase0DomainAxiom");
        // Not a trust marker → NOT blocked by the Phase-0 gate ...
        assert!(
            term_reaches_no_trust_marker(env.clone(), &false_ty, &term),
            "a non-marker domain axiom is out of Phase-0 gate scope (trust markers only)"
        );
        // ... but it IS surfaced by the kernel's dependency walker (visible, not hidden).
        let probe = Name::from_string("__ty_phase0_domain_axiom_probe__");
        env.add_decl_structural(Declaration::Theorem {
            name: probe.clone(),
            level_params: Vec::new(),
            type_: false_ty.clone(),
            value: term.clone(),
        })
        .expect("structural insert of the probe theorem");
        assert!(
            env.axiom_deps(&probe)
                .is_some_and(|d| d.iter().any(|n| n.to_string() == "TyPhase0DomainAxiom")),
            "axiom_deps must SURFACE the admitted domain axiom (the verdict is honestly AxiomDependent)"
        );
    }

    /// Positive control: an axiom-free term still promotes, so the gate is not vacuously rejecting
    /// everything. (The existing cleancic kernel tests are the broader positive regression suite.)
    #[test]
    fn gate_admits_axiom_free_identity_term() {
        assert!(
            kernel_accepts(&polymorphic_identity_term(), &polymorphic_identity_type()),
            "λP.λh.h : ∀P.P→P cites no axioms and must remain Certified after the Phase-0 gate"
        );
    }

    #[test]
    fn faithful_int_encoder_produces_kernel_typed_props() {
        // Encode `x + 1 ≥ 0` faithfully (→ Int.le 0 (Int.add x 1)); under λ(x:Int) the kernel must
        // accept it as a well-typed Prop — the general Int-expression embedding, kernel-validated.
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::Ident("x".to_string(), NameId::INVALID);
        let atom_idx =
            |e: &E| -> Option<u32> { matches!(e, E::Ident(n, _) if n == "x").then_some(0) };
        // x + 1 ≥ 0
        let pred = E::Geq(
            sp(E::Add(sp(x()), sp(E::Int(num_bigint::BigInt::from(1))))),
            sp(E::Int(num_bigint::BigInt::from(0))),
        );
        let enc = encode_int_pred(&pred, &atom_idx).expect("encodes within the Int fragment");
        let wrapped = Expr::lam(BinderInfo::Default, Expr::const_str("Int"), enc);
        assert!(
            kernel_well_typed(&wrapped),
            "the faithfully-encoded Int predicate must be kernel-well-typed under x:Int"
        );
        // A non-arithmetic construct is outside the fragment → None (fail-closed, not mis-encoded).
        assert!(encode_int_pred(&E::Bool(true), &atom_idx).is_none());
    }

    #[test]
    fn native_lane_capture_drain_builds_cert() {
        let _ = take_native_lane_cert(); // clear any state from a prior test on this thread
        capture_native_sample(7, vec![3, 7, 11]);
        capture_native_sample(99, vec![1]); // first-wins → ignored
        let bytes = take_native_lane_cert().expect("captured 7 ∈ {3,7,11} → kernel-checked cert");
        assert!(!bytes.is_empty());
        assert!(take_native_lane_cert().is_none(), "drained — nothing left");
        // A captured native value NOT interpreter-reachable → no cert (fail-closed, surfaces a bug).
        capture_native_sample(9, vec![3, 7, 11]);
        assert!(take_native_lane_cert().is_none());
    }

