    #[test]
    fn kernel_accepts_native_membership_relation_inclusion() {
        // NATIVE LANE (meaningful direction): the JIT's successor value 7 is interpreter-reachable —
        // 7 ∈ {3,7,11} — proved by Or-injection into the membership disjunction (NON-trivial).
        let (ty, term) = native_membership_cert(7, &[3, 7, 11]).expect("7 is reachable");
        assert!(
            kernel_accepts(&term, &ty),
            "the kernel must check native successor 7 ∈ interpreter set {{3,7,11}}"
        );
        // First and last positions.
        let (t0, m0) = native_membership_cert(3, &[3, 7, 11]).unwrap();
        assert!(kernel_accepts(&m0, &t0));
        let (t2, m2) = native_membership_cert(11, &[3, 7, 11]).unwrap();
        assert!(kernel_accepts(&m2, &t2));
        // A native successor NOT in the interpreter set → None (a real JIT divergence, fail-closed).
        assert!(native_membership_cert(9, &[3, 7, 11]).is_none());
    }

    #[test]
    fn kernel_accepts_native_sample_equiv() {
        // NATIVE LANE (P0 sampled→proven): a sampled state where native and interpreter successors
        // agree per-variable — x:5=5, y:3=3, z:0=0 — is kernel-PROVEN equivalent (⋀ Eq.refl).
        let (ty, term) = native_sample_equiv_cert(&[(5, 5), (3, 3), (0, 0)]).expect("agreement");
        assert!(
            kernel_accepts(&term, &ty),
            "the kernel must check the per-sample native==interpreter equivalence"
        );
        // Divergence on any variable → no equivalence certificate (fail-closed, surfaces a real bug).
        assert!(native_sample_equiv_cert(&[(5, 5), (3, 4)]).is_none());
        assert!(native_sample_equiv_cert(&[]).is_none());
    }

