        // case-split via Or.rec, each branch Eq.trans + Or.inl/inr — kernel-checked. With the
        // membership leg this completes the fixpoint witness (Init⊆R ∧ closed ∧ R⊆Safety).
        let (ty, term) = explicit_closed_2state(3, 7);
