    #[test]
    fn explicit_fixpoint_set_certify_and_recheck() {
        // SCALAR (1-tuple) end-to-end: R={2,5,9}, Init {2,5} ⊆ R, NON-STUTTER image {5,9}. All three
        // legs (tuple Init⊆R, image-closure, R⊆Safety) kernel-checked at emit AND re-check.
        let reachable: Vec<Vec<u64>> = vec![vec![9], vec![2], vec![5]]; // unsorted — canonicalized inside
        let init_values: Vec<Vec<u64>> = vec![vec![5], vec![2]];
        let image: Vec<Vec<u64>> = vec![vec![5], vec![9]];
        let s1 = all_int(1);
        let (closed, safety, init_terms) =
            certify_explicit_fixpoint_set(&reachable, &init_values, &image, &s1)
                .expect("scalar fixpoint set certifies");
        assert_eq!(init_terms.len(), 2);
        assert_eq!(
            closed.len(),
            2,
            "one closed-leg membership per distinct image tuple"
        );
        assert!(verify_explicit_fixpoint_set(
            &reachable,
            &init_values,
            &image,
            &s1,
            &closed,
            &safety,
            &init_terms
        ));
        // Init NOT in R / successor NOT in R / cross-set replay → all fail-closed.
        assert!(
            certify_explicit_fixpoint_set(&reachable, &[vec![2], vec![7]], &image, &s1).is_none()
        );
        assert!(
            certify_explicit_fixpoint_set(&reachable, &init_values, &[vec![5], vec![99]], &s1)
                .is_none()
        );
        assert!(!verify_explicit_fixpoint_set(
            &[vec![2], vec![5], vec![9], vec![100]],
            &init_values,
            &image,
            &s1,
            &closed,
            &safety,
            &init_terms
        ));

        // MULTI-VARIABLE (2-tuple) end-to-end: R={(0,2),(3,4),(7,1)}, Init {(0,2),(7,1)}, non-stutter
        // image {(0,2),(3,4)} — the And-conjunction tuple membership + per-variable ⋀_j x_j≥0 safety.
        let r2: Vec<Vec<u64>> = vec![vec![7, 1], vec![0, 2], vec![3, 4]];
        let iv2: Vec<Vec<u64>> = vec![vec![0, 2], vec![7, 1]];
        let img2: Vec<Vec<u64>> = vec![vec![0, 2], vec![3, 4]];
        let s2v = all_int(2);
        let (c2, s2, i2) = certify_explicit_fixpoint_set(&r2, &iv2, &img2, &s2v)
            .expect("2-variable tuple fixpoint certifies");
        assert!(verify_explicit_fixpoint_set(
            &r2, &iv2, &img2, &s2v, &c2, &s2, &i2
        ));
        // Ragged arity → fail-closed.
        assert!(certify_explicit_fixpoint_set(
            &[vec![0, 2], vec![3]],
            &[vec![0, 2]],
            &[vec![0, 2]],
            &s2v
        )
        .is_none());
        // A 3-variable singleton certifies + re-checks.
        let r3: Vec<Vec<u64>> = vec![vec![1, 2, 3]];
        let s3v = all_int(3);
        let (c3, s3, i3) =
            certify_explicit_fixpoint_set(&r3, &r3, &r3, &s3v).expect("3-var singleton certifies");
        assert!(verify_explicit_fixpoint_set(
            &r3, &r3, &r3, &s3v, &c3, &s3, &i3
        ));
    }

    #[test]
    fn kernel_accepts_mixed_int_bool_tuple_legs() {
        // MIXED Int/Bool tuple sets: the Init⊆R membership, closed-under-Next (stutter) leg, and the
        // R⊆Safety leg (⋀_{Int} x≥0, NO conjunct for Bool columns) must ALL kernel-check — direct
        // kernel-ABI validation of the per-column-sort tuple encoding (Eq Int / Eq Bool, ofNat /
        // Bool.true|false). Bool encoded 1→true, 0→false.
        use ColSort::{Bool, Int};
        struct Case {
            sorts: Vec<ColSort>,
            set: Vec<Vec<u64>>,
        }
        let cases = vec![
            // (Int, Bool): R={(0,true),(2,false)}.
            Case {
                sorts: vec![Int, Bool],
                set: vec![vec![0, 1], vec![2, 0]],
            },
            // (Bool, Int): leading Bool column.
            Case {
                sorts: vec![Bool, Int],
                set: vec![vec![1, 3], vec![0, 7]],
            },
            // (Int, Bool, Int): Bool in the middle, two Int columns.
            Case {
                sorts: vec![Int, Bool, Int],
                set: vec![vec![0, 0, 5], vec![4, 1, 2], vec![9, 0, 0]],
            },
            // Singleton mixed tuple (degenerate disjunction).
            Case {
                sorts: vec![Int, Bool],
                set: vec![vec![6, 1]],
            },
        ];
        for c in &cases {
            let r = &c.set;
            let s = &c.sorts;
            let (ct, cterm) = explicit_closed_tuple(r, s);
            assert!(
                kernel_accepts(&cterm, &ct),
                "closed leg must kernel-check for {r:?} sorts {s:?}"
            );
            let (st, sterm) = explicit_safety_tuple(r, s);
            assert!(
                kernel_accepts(&sterm, &st),
                "R⊆Safety leg must kernel-check for {r:?} sorts {s:?}"
            );
            for which in 0..r.len() {
                assert!(
                    kernel_accepts(
                        &tuple_membership_term(r, which, s),
                        &tuple_membership_type(r, which, s)
                    ),
                    "membership {which} must kernel-check for {r:?} sorts {s:?}"
                );
                let (cty, cmem) = concrete_tuple_membership(r, &r[which], s).expect("member ∈ R");
                assert!(
                    kernel_accepts(&cmem, &cty),
                    "concrete membership {which} for {r:?}"
                );
            }
        }
        // End-to-end certify + re-check over a mixed Int/Bool set with a non-stutter image.
        let sorts = vec![Int, Bool];
        let reachable: Vec<Vec<u64>> = vec![vec![0, 1], vec![1, 1]];
        let init: Vec<Vec<u64>> = vec![vec![0, 1]];
        let image: Vec<Vec<u64>> = vec![vec![1, 1]]; // 0→1 on the Int column, Bool stays true
        let (closed, safety, init_terms) =
            certify_explicit_fixpoint_set(&reachable, &init, &image, &sorts)
                .expect("mixed Int/Bool fixpoint certifies");
        assert!(verify_explicit_fixpoint_set(
            &reachable,
            &init,
            &image,
            &sorts,
            &closed,
            &safety,
            &init_terms
        ));
        // Sort vector with NO Int column (R3): the base legs now certify with the TRIVIAL
        // `Eq Bool true true` safety codomain — the spec's real Safety claim must ride the
        // general `safety_general` leg (the orchestrator guarantees it: `verify_explicit_state_cert`
        // rejects a no-Int cert without `safety_pred`).
        {
            let (bclosed, bsafety, binit) =
                certify_explicit_fixpoint_set(&[vec![1], vec![0]], &[vec![1]], &[vec![1]], &[Bool])
                    .expect("an all-Bool state certifies with the trivial safety codomain");
            assert!(verify_explicit_fixpoint_set(
                &[vec![1], vec![0]],
                &[vec![1]],
                &[vec![1]],
                &[Bool],
                &bclosed,
                &bsafety,
                &binit
            ));
        }
        // Sort vector arity mismatch → fail-closed.
        assert!(
            certify_explicit_fixpoint_set(&reachable, &init, &image, &[Int]).is_none(),
            "sort vector arity must match the tuple width"
        );
    }

    #[test]
    fn kernel_accepts_explicit_tuple_legs() {
        // MULTI-VARIABLE legs directly: for several tuple sets (varying arity + cardinality) the
        // closed-under-Next (universal stutter) leg, the R⊆Safety leg, and each tuple membership all
        // kernel-check — direct kernel-ABI validation of the And-conjunction tuple encoding.
        let sets: Vec<Vec<Vec<u64>>> = vec![
            vec![vec![7]],                                                    // 1-var singleton
            vec![vec![2], vec![5], vec![9]], // 1-var multi (= scalar legs)
            vec![vec![0, 2], vec![3, 4], vec![7, 1]], // 2-var
            vec![vec![1, 2, 3]],             // 3-var singleton
            vec![vec![0, 0, 0], vec![1, 2, 3], vec![4, 5, 6], vec![9, 8, 7]], // 3-var multi
        ];
        for r in &sets {
            let s = all_int(r[0].len());
            let (ct, cterm) = explicit_closed_tuple(r, &s);
            assert!(
                kernel_accepts(&cterm, &ct),
                "closed-under-Next tuple leg must kernel-check for R={r:?}"
            );
            let (st, sterm) = explicit_safety_tuple(r, &s);
            assert!(
                kernel_accepts(&sterm, &st),
                "R⊆Safety tuple leg must kernel-check for R={r:?}"
            );
            for which in 0..r.len() {
                assert!(
                    kernel_accepts(
                        &tuple_membership_term(r, which, &s),
                        &tuple_membership_type(r, which, &s)
                    ),
                    "tuple membership for member {which} must kernel-check for R={r:?}"
                );
            }
        }
    }

    #[test]
    fn kernel_reevaluates_next_rejects_underapproximated_image() {
        // THE SOUNDNESS WIN: the kernel itself RE-EVALUATES Next over the whole finite domain D, so it
        // catches an enumerator UNDER-approximation that the `image ⊆ R`-only leg cannot.
        // Counter `Next == x' = x + 1 /\ x < N` with Init x=0 → R = {0..N}; domain D = {0..=N}.
        let n = 20u64;
        let shape = AffineNextShape { delta: 1, bound: n };
        let domain: Vec<u64> = (0..=n).collect();
        let r_full: Vec<u64> = (0..=n).collect();
        // Correct R: the kernel re-evaluates Next over all of D and ACCEPTS (R is closed).
        assert!(
            certify_next_completeness(&r_full, &domain, &shape).is_some(),
            "the kernel must accept the genuinely closed reachable set R={{0..{n}}}"
        );
        // Enumerator "missed" successor 7 (6→7 is admitted by Next but 7∉R): R is NOT closed. The kernel
        // REJECTS — exactly the under-approximation the old `image ⊆ R` leg passes vacuously on (a missing
        // successor just shortens the enumerated `image`, every element of which is still in R).
        let r_broken: Vec<u64> = (0..=n).filter(|&x| x != 7).collect();
        assert!(
            certify_next_completeness(&r_broken, &domain, &shape).is_none(),
            "the kernel must REJECT an under-approximated R (missing the real successor 7)"
        );
        // Serialized round-trip: the witness re-checks for the closed set, fails for the broken one.
        let bytes = certify_next_completeness(&r_full, &domain, &shape).unwrap();
        assert!(verify_next_completeness(&r_full, &domain, &shape, &bytes));
        assert!(!verify_next_completeness(
            &r_broken, &domain, &shape, &bytes
        ));
        // A larger increment whose successors exceed the guard bound still reduces correctly: δ=2,
        // bound=3, Init 0 → R={0,2,4} (0→2→4, 4<3 false stops), domain must cover the successor 4.
        let s2 = AffineNextShape { delta: 2, bound: 3 };
        let d2: Vec<u64> = (0..=5).collect();
        assert!(
            certify_next_completeness(&[0, 2, 4], &d2, &s2).is_some(),
            "R={{0,2,4}} is closed"
        );
        assert!(
            certify_next_completeness(&[0, 2], &d2, &s2).is_none(),
            "missing successor 4 → reject"
        );
    }

    /// Parse a full module spec and return the body AST of operator `name`.
    fn op_body(spec: &str, name: &str) -> tla_core::ast::Expr {
        let tree = tla_core::parse_to_syntax_tree(spec);
        let module = tla_core::lower(tla_core::FileId(0), &tree)
            .module
            .expect("module");
        for u in &module.units {
            if let tla_core::ast::Unit::Operator(op) = &u.node {
                if op.name.node == name {
                    return op.body.node.clone();
                }
            }
        }
        panic!("operator {name} not found");
    }

    #[test]
    fn kernel_evaluates_general_nonaffine_next() {
        // THE GENERAL EMBEDDER: the kernel evaluates an ARBITRARY `Next` predicate AST (not a hardcoded
        // shape) via embed_pred — arbitrary nonneg arithmetic + Boolean structure.
        // (1) NON-AFFINE multiplicative update `x' = x * 2 /\ x < 4`, Init x=1 → R={1,2,4} (1→2→4, 4<4
        // false stops). The kernel computes `Nat.mul` + the guard.
        let mul = op_body(
            "---- MODULE M ----\nEXTENDS Integers\nVARIABLE x\nNext == x' = x * 2 /\\ x < 4\n====\n",
            "Next",
        );
        let d: Vec<u64> = (0..=8).collect();
        assert!(
            certify_next_completeness_general(&[1, 2, 4], &d, &mul, "x").is_some(),
            "kernel evaluates x'=x*2 ∧ x<4 and confirms R={{1,2,4}} is closed"
        );
        assert!(
            certify_next_completeness_general(&[1, 4], &d, &mul, "x").is_none(),
            "missing the real successor 2 (1→2) → kernel REJECTS"
        );
        // (2) Extra conjuncts + a disjunctive/Boolean guard the affine recognizer would NOT match, but
        // the general embedder evaluates: `x' = x + 1 /\ (x < 3 \/ FALSE) /\ x >= 0` → R={0,1,2,3}.
        let rich = op_body(
            "---- MODULE M ----\nEXTENDS Integers\nVARIABLE x\nNext == x' = x + 1 /\\ (x < 3 \\/ FALSE) /\\ x >= 0\n====\n",
            "Next",
        );
        let d2: Vec<u64> = (0..=4).collect();
        assert!(
            certify_next_completeness_general(&[0, 1, 2, 3], &d2, &rich, "x").is_some(),
            "kernel evaluates the rich Boolean Next and confirms R={{0,1,2,3}} closed"
        );
        assert!(
            certify_next_completeness_general(&[0, 1, 3], &d2, &rich, "x").is_none(),
            "missing successor 2 → kernel REJECTS"
        );
    }

    #[test]
    fn kernel_evaluates_finite_set_theory() {
        // SET THEORY in CIC: the kernel REDUCES TLA+ finite-set relations to Bool — it evaluates ∈, ⊆,
        // =, bounded ∀/∃, and (extensional) ∪ over concrete finite sets of Nat.
        let acc = |c: Expr| {
            let (ty, t) = bool_true_eq(c);
            kernel_accepts(&t, &ty)
        };
        // ∈ : 2 ∈ {1,2,3} ; 5 ∉ {1,2,3} ; nothing ∈ {}
        assert!(acc(set_mem_bool(2, &[1, 2, 3])));
        assert!(!acc(set_mem_bool(5, &[1, 2, 3])));
        assert!(!acc(set_mem_bool(0, &[])));
        // ⊆ : {1,2} ⊆ {1,2,3} ; {1,4} ⊄ {1,2,3} ; {} ⊆ S
        assert!(acc(set_subseteq_bool(&[1, 2], &[1, 2, 3])));
        assert!(!acc(set_subseteq_bool(&[1, 4], &[1, 2, 3])));
        assert!(acc(set_subseteq_bool(&[], &[1, 2, 3])));
        // = : {1,2,3} = {3,2,1} (order/duplication-independent) ; {1,2} ≠ {1,2,3}
        assert!(acc(set_eq_bool(&[1, 2, 3], &[3, 2, 1])));
        assert!(!acc(set_eq_bool(&[1, 2], &[1, 2, 3])));
        // bounded quantifiers: ∀x∈{1,2,3}: x∈{1,2,3,4} ; ¬∃x∈{5,6}: x∈{1,2,3} ; ∃x∈{5,2}: x∈{1,2,3}
        assert!(acc(set_forall_bool(&[1, 2, 3], |x| set_mem_bool(
            x,
            &[1, 2, 3, 4]
        ))));
        assert!(!acc(set_exists_bool(&[5, 6], |x| set_mem_bool(
            x,
            &[1, 2, 3]
        ))));
        assert!(acc(set_exists_bool(&[5, 2], |x| set_mem_bool(
            x,
            &[1, 2, 3]
        ))));
        // UNION evaluated EXTENSIONALLY by the kernel (no Rust set-union): over element universe U,
        // {1,2,3} = {1,2} ∪ {2,3} iff ∀x∈U: x∈{1,2,3} ⟺ (x∈{1,2} ∨ x∈{2,3}).
        let (s1, s2, s3): (&[u64], &[u64], &[u64]) = (&[1, 2], &[2, 3], &[1, 2, 3]);
        let iff = |x: u64| {
            let lhs = set_mem_bool(x, s3);
            let rhs = Expr::apps(
                Expr::const_str("Bool.or"),
                [set_mem_bool(x, s1), set_mem_bool(x, s2)],
            );
            let bnot = |e: Expr| Expr::apps(Expr::const_str("Bool.not"), [e]);
            Expr::apps(
                Expr::const_str("Bool.or"),
                [
                    Expr::apps(Expr::const_str("Bool.and"), [lhs.clone(), rhs.clone()]),
                    Expr::apps(Expr::const_str("Bool.and"), [bnot(lhs), bnot(rhs)]),
                ],
            )
        };
        assert!(
            acc(set_forall_bool(&[1, 2, 3], iff)),
            "kernel evaluates {{1,2,3}} = {{1,2}} ∪ {{2,3}} extensionally"
        );
    }

    #[test]
    fn ir_domain_bound_recomputes_matching_ast() {
        // Hardening: verify RECOMPUTES the domain bound from the IR (never trusts a serialized `hi`, so a
        // re-sealed crafted cert cannot shrink D to hide an escaping successor). The IR-recomputed bound
        // must equal the AST-derived bound certify used — so the correct D is rebuilt, no regression.
        let next = op_body(
            "---- MODULE M ----\nEXTENDS Integers\nVARIABLE x\nNext == x' = x + 2 /\\ x' < 9\n====\n",
            "Next",
        );
        let ast_hi = next_domain_bound(&next, "x").expect("AST domain bound from x' < 9");
        let ir = recognize_pred(&next, &["x"]).expect("Next recognizes to a PredIR");
        let ir_hi = next_domain_bound_from_ir(&ir).expect("IR domain bound");
        assert_eq!(
            ir_hi, ast_hi,
            "IR-recomputed bound must match the AST bound"
        );
        assert_eq!(ir_hi, 8, "H = 8 read straight off the primed bound x' < 9");
    }

    #[test]
    fn kernel_accepts_explicit_state_membership() {
        // EXPLICIT-STATE: a finite reachable set R={3,7,11}; for each member, x=rᵢ ⇒ x∈R is
        // kernel-checked via Or.inl/Or.inr navigation — the Init⊆R / R⊆Safety disjunction reasoning.
        let states = [3u64, 7, 11];
        for which in 0..states.len() {
            assert!(
                kernel_accepts(
                    &explicit_membership_term(&states, which),
                    &explicit_membership_type(&states, which)
                ),
                "x=r{which} ⇒ x∈{{3,7,11}} must be kernel-checked"
            );
        }
        // Singleton set: degenerates to the bare equality (no Or).
        assert!(kernel_accepts(
            &explicit_membership_term(&[5], 0),
            &explicit_membership_type(&[5], 0)
        ));
    }

    #[test]
    fn kernel_accepts_violated_multistep_trace() {
        // Counter Next: x'=x+1 from x=0, Safety: x≤3. Trace 0→1→2→3→4 violates at s4=4.
        // Witness: Init(0=0) ∧ (1=0+1) ∧ (2=1+1) ∧ (3=2+1) ∧ (4=3+1) ∧ (3<4) — all kernel-checked.
        let (ty, term) = violated_trace_le(0, 4, 3).expect("trace reaches a violation");
        assert!(
            kernel_accepts(&term, &ty),
            "the kernel must check the full multi-step counterexample trace"
        );
        // Longer trace, nonzero start.
        let (ty2, term2) = violated_trace_le(5, 10, 12).expect("5→15 violates x≤12");
        assert!(kernel_accepts(&term2, &ty2));
        // Never reaches the bound → no violation → None (fail-closed).
        assert!(violated_trace_le(0, 2, 3).is_none());
    }

    #[test]
    fn violated_init_delivered_from_spec_exprs() {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::Ident("x".to_string(), NameId::INVALID);
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        // Init: x = 5, Safety: x ≤ 3 — refuted at the initial state.
        let init = E::Eq(sp(x()), sp(lit(5)));
        let safety = E::Leq(sp(x()), sp(lit(3)));
        let bytes = certify_violated_init(&init, &safety)
            .expect("x=5 violates x≤3 → kernel-checked counterexample");
        assert!(
            verify_violated_init(&init, &safety, &bytes),
            "obligation-aware re-check accepts"
        );
        // No violation (x=2 satisfies x≤3) → no counterexample certificate (fail-closed).
        let init_ok = E::Eq(sp(x()), sp(lit(2)));
        assert!(certify_violated_init(&init_ok, &safety).is_none());
    }

    #[test]
    fn kernel_accepts_violated_init_counterexample() {
        // VIOLATED class: Init x=5 violates Safety x≤3. Witness And (5=5) (3<5), kernel-checked —
        // a sound counterexample that an initial state is unsafe, reduced to the Clean kernel.
        assert!(
            kernel_accepts(
                &violated_init_le_term(5, 3).unwrap(),
                &violated_init_le_type(5, 3)
            ),
            "the kernel must check the x=5 violates x≤3 counterexample"
        );
        // Larger gap.
        assert!(kernel_accepts(
            &violated_init_le_term(100, 0).unwrap(),
            &violated_init_le_type(100, 0)
        ));
        // No violation (c ≤ d) → no certificate (fail-closed).
        assert!(violated_init_le_term(3, 5).is_none());
        assert!(violated_init_le_term(4, 4).is_none());
    }

    #[test]
    fn certify_violated_trace_general_from_real_trace_shapes() {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        // The LIVE lowering spells the variable `StateVar`, not `Ident` — exercise that path.
        let x = || E::StateVar("x".to_string(), 0, NameId::INVALID);
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        // Init: x=0, Next: x'=x+1, Safety: x<3 — the real counter spec.
        let init = E::Eq(sp(x()), sp(lit(0)));
        let next = E::Eq(sp(E::Prime(sp(x()))), sp(E::Add(sp(x()), sp(lit(1)))));
        let safety = E::Lt(sp(x()), sp(lit(3)));

        // The real violating trace the checker would find.
        let bytes = certify_violated_trace(&init, &next, &safety, "x", &[0, 1, 2, 3])
            .expect("x=0→1→2→3 violates x<3 → kernel-checked finite-trace cert");
        assert!(verify_violated_trace(
            &init,
            &next,
            &safety,
            "x",
            &[0, 1, 2, 3],
            &bytes
        ));

        // Fail-closed: a NON-violating final state (x=2 still satisfies x<3) → no cert.
        assert!(certify_violated_trace(&init, &next, &safety, "x", &[0, 1, 2]).is_none());
        // Fail-closed: a trace whose Next step doesn't hold (0→2 is not 0+1) → no cert.
        assert!(certify_violated_trace(&init, &next, &safety, "x", &[0, 2, 3]).is_none());
        // Fail-closed: a trace whose Init doesn't hold (starts at 1, not 0) → no cert.
        assert!(certify_violated_trace(&init, &next, &safety, "x", &[1, 2, 3]).is_none());
        // Tamper: a cert for [0,1,2,3] must NOT re-check against [0,1,2,3,4].
        assert!(!verify_violated_trace(
            &init,
            &next,
            &safety,
            "x",
            &[0, 1, 2, 3, 4],
            &bytes
        ));

        // Single-state (initial-only) violation: Safety x≤2 violated at x=5 (Init x=5).
        let init5 = E::Eq(sp(x()), sp(lit(5)));
        let safety_le2 = E::Leq(sp(x()), sp(lit(2)));
        let b2 = certify_violated_trace(&init5, &next, &safety_le2, "x", &[5])
            .expect("x=5 violates x≤2 at the initial state");
        assert!(verify_violated_trace(
            &init5,
            &next,
            &safety_le2,
            "x",
            &[5],
            &b2
        ));
    }

    #[test]
    fn certify_violated_trace_out_of_fragment_is_none() {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::StateVar("x".to_string(), 0, NameId::INVALID);
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        let init = E::Eq(sp(x()), sp(lit(0)));
        let next = E::Eq(sp(E::Prime(sp(x()))), sp(E::Add(sp(x()), sp(lit(1)))));
        // Safety is a SET-membership (not an Int comparison) → out of fragment → no cert.
        let safety_set = E::And(sp(E::Eq(sp(x()), sp(x()))), sp(E::Eq(sp(x()), sp(x()))));
        assert!(certify_violated_trace(&init, &next, &safety_set, "x", &[0, 1, 2, 3]).is_none());
        // Empty trace → no cert.
        assert!(
            certify_violated_trace(&init, &next, &E::Lt(sp(x()), sp(lit(3))), "x", &[]).is_none()
        );
    }

    #[test]
    fn kernel_accepts_ground_nonneg_init() {
        // x=c ⇒ x≥0 for nonneg c — the ground init implication, faithfully encoded (real Int.le,
        // real Int.ofNat_zero_le) and kernel-checked at its exact type. Closes the congruence gap.
        for c in [0u64, 3, 42] {
            assert!(
                kernel_accepts(&ground_nonneg_init_term(c), &ground_nonneg_init_type(c)),
                "x={c} ⇒ x≥0 must be kernel-certified"
            );
        }
    }

    #[test]
    fn faithful_int_congruence_live_certify_and_recheck() {
        use tla_core::ast::Expr as E;
        use tla_core::{NameId, Spanned};
        let sp = |e: E| Box::new(Spanned::dummy(e));
        let x = || E::Ident("x".to_string(), NameId::INVALID);
        let lit = |n: i64| E::Int(num_bigint::BigInt::from(n));
        let j = E::Geq(sp(x()), sp(lit(0))); // x ≥ 0
        let next = E::Eq(sp(E::Prime(sp(x()))), sp(x())); // x' = x (stutter)

        let bytes = certify_int_congruence(&j, &next)
            .expect("x≥0 preserved under x'=x must be kernel-certified (faithful Int.le)");
        assert!(
            verify_int_congruence(&j, &next, &bytes),
            "obligation-aware re-check accepts"
        );
        // x'=x+1 is not a stutter — the congruence does not apply.
        let next_inc = E::Eq(sp(E::Prime(sp(x()))), sp(E::Add(sp(x()), sp(lit(1)))));
        assert!(
            certify_int_congruence(&j, &next_inc).is_none(),
            "a changing variable yields no congruence certificate"
        );
        // The proof is BOUND to x≥0: re-checking it as x≥1 must fail (different real Int.le literal).
        let j_ge1 = E::Geq(sp(x()), sp(lit(1)));
        assert!(
            !verify_int_congruence(&j_ge1, &next, &bytes),
            "a proof of x≥0 must not satisfy the x≥1 obligation"
        );
    }

    #[test]
    fn kernel_accepts_faithful_nonneg_congruence() {
        // The kernel checks the FAITHFUL `x≥0 ∧ x'=x ⇒ x'≥0` proof at its EXACT type — real Int.le,
        // real literal `0` — so the proof is bound to the ACTUAL `≥0` predicate (faithfulness by the
        // real encoding, not an opaque stand-in). First piece of the faithful Int embedding.
        assert!(
            kernel_accepts(
                &faithful_nonneg_congruence_term(),
                &faithful_nonneg_congruence_type()
            ),
            "the kernel must check the faithful x≥0 congruence at its real Int.le type"
        );
    }

